from itertools import product

# Each athlete is a tuple (P=participates, S=strong, R=rarely sick, U=unwell).
# Premises: P->S, S->R, and some athlete is U and not P.
# "Seldom/rarely sick" is treated as a plain predicate R.
types = [t for t in product([0, 1], repeat=4)
         if (not t[0] or t[1]) and (not t[1] or t[2])]  # P->S, S->R per athlete

def premise(w):
    return any(a[3] and not a[0] for a in w)

opts = {
    "A: some unwell are rarely sick":  lambda w: any(a[3] and a[2] for a in w),
    "B: participants are rarely sick": lambda w: all((not a[0]) or a[2] for a in w),
    "C: some rarely sick are unwell":  lambda w: any(a[2] and a[3] for a in w),
    "D: some strong are unwell":       lambda w: any(a[1] and a[3] for a in w),
}

entailed = {k: True for k in opts}
counter = {}
for n in range(1, 4):  # exhaustive over all worlds with 1..3 athletes
    for w in product(types, repeat=n):
        if not premise(w):
            continue
        for k, f in opts.items():
            if not f(w):
                entailed[k] = False
                counter.setdefault(k, w)

for k in opts:
    print(k, "| entailed:", entailed[k], "| counterexample:", counter.get(k))

non_derivable = [k[0] for k in opts if not entailed[k]]
print("Non-derivable options:", non_derivable)

if non_derivable == ["A"]:
    print("CHECK PASS")
elif "A" in non_derivable:
    print("A is not derivable, but so are others, so the question has no unique answer;")
    print("A and C are logically equivalent, so A cannot be the unique non-derivable option.")
    print("The submitted answer is not uniquely confirmed (a key of D would conflict with it).")
    print("CHECK UNKNOWN")
else:
    print("CHECK FAIL")
